/** The English documents. Screens use getLegalDocuments(locale). */
export const LEGAL_DOCUMENTS: LegalDocument[] = [TERMS, PRIVACY, HEALTH];

export const getLegalDocuments = (locale: Locale = 'en'): LegalDocument[] =>
  locale === 'fi' ? LEGAL_DOCUMENTS_FI : LEGAL_DOCUMENTS;

export const getLegalDocument = (
  id: LegalDocId,
  locale: Locale = 'en',
): LegalDocument | undefined => getLegalDocuments(locale).find(doc => doc.id === id);
